class ReconciliationLoop:
    def __init__(self, desired_replicas):
        self.desired_replicas = desired_replicas
        self.pods = [f"pod-{i}" for i in range(desired_replicas)]

    def node_failure_kills(self, pod_name):
        if pod_name in self.pods:
            self.pods.remove(pod_name)

    def reconcile(self):
        """Bring actual state back to the desired state."""
        next_id = 0
        while len(self.pods) < self.desired_replicas:
            name = f"pod-new-{next_id}"
            self.pods.append(name)
            next_id += 1
        while len(self.pods) > self.desired_replicas:
            self.pods.pop()


deployment = ReconciliationLoop(desired_replicas=3)
print("initial pods:", deployment.pods)

deployment.node_failure_kills("pod-1")
print("after node failure:", deployment.pods)

deployment.reconcile()
print("after reconciliation:", deployment.pods)
print("replica count matches desired:", len(deployment.pods) == deployment.desired_replicas)
